{"output":"import { api } from '../../utils/api';
import { submitTurnTelemetry } from '../../utils/telemetry';

const DEFAULT_THEME_ID = 'palace-survival';
const MAX_PARALLEL_LOADS = 3;

const createPanelState = (themeId, title = '') => ({
  themeId,
  title,
  sessionId: '',
  narrative: '',
  options: [],
  ending: false,
  moderationMessage: '',
  turnCount: 0,
  isLoading: false,
  pendingAction: '',
  isInitialized: false,
  lastError: '',
  scrollTop: 0
});

Page({
  currentModelProvider: 'qwen',
  loadingQueue: [],
  activeLoads: new Set(),
  panelIndexMap: {},
  panelScrollPositions: {},

  data: {
    themePanels: [],
    activeIndex: 0
