    this.currentModelProvider = provider;
    return provider;
  },

  updateActivePanelState() {
    const activePanel = this.data.themePanels[this.data.activeIndex];
    if (!activePanel) {
      return;
    }
    this.setData({});
  },

  onSwitchTheme(event) {
    const { direction } = event.currentTarget.dataset;
    if (direction === 'up') {
      this.switchPanel(-1);
    } else if (direction === 'down') {
      this.switchPanel(1);
    }
  },

  switchPanel(offset) {
    if (!offset) {
