  '✨ 正在进行最终润色与校验(7/7)…'
];

const INTERACTION_MESSAGES = [
  '🧩 正在分析你的选择(1/6)…',
  '🤔 AI 正在预测剧情走向(2/6)…',
  '🔄 正在调整故事结构以匹配你的决定(3/6)…',
