下面是一段最小可跑的 Node.js（18+）范例，请把它保存成 `stream-qwen.js` 后在终端执行 `DASHSCOPE_API_KEY=你的密钥 node stream-qwen.js`。脚本会向 DashScope 的兼容模式接口发起 `stream: true` 请求，并逐行打印服务端推送的内容。

```js
// stream-qwen.js
const endpoint = 'https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions';

async function main() {
  const apiKey = process.env.DASHSCOPE_API_KEY;
  if (!apiKey) {
    console.error('Missing DASHSCOPE_API_KEY env var');
    process.exit(1);
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`
    },
    body: JSON.stringify({
      model: 'qwen-plus',          // 或 qwen-flash
      stream: true,                // 关键：启用流式
      messages: [
        { role: 'system', content: '你是一位中文故事写手。' },
        { role: 'user', content: '写一段穿越宫廷题材的开头，风格紧凑。' }
      ]
    })
  });

  if (!response.ok || !response.body) {
    console.error(`HTTP ${response.status}: ${await response.text()}`);
    process.exit(1);
  }

  const decoder = new TextDecoder();

  for await (const chunk of response.body) {
    const text = decoder.decode(chunk, { stream: true });
    text
      .split('\n')
      .filter((line) => line.startsWith('data:'))
      .forEach((line) => {
        const payload = line.slice(5).trim();
        if (payload === '[DONE]') {
          console.log('\n--- stream end ---');
          return;
        }
        try {
          const event = JSON.parse(payload);
          const delta = event.choices?.[0]?.delta?.content;
          if (delta) process.stdout.write(delta);
        } catch (err) {
          console.warn('Failed to parse chunk:', payload);
        }
      });
  }
}

main().catch((err) => {
  console.error('Stream request failed:', err);
  process.exit(1);
});
```

> 运行前请确保：
> 1. 你有有效的 DashScope/Qwen API Key，并放在环境变量 `DASHSCOPE_API_KEY` 中；
> 2. 终端所在机器能访问 `dashscope.aliyuncs.com`；
> 3. Node.js 版本 ≥ 18（默认内置 `fetch` 和 `ReadableStream`）。

执行后你会看到模型内容一段段刷出来，最后打印 `--- stream end ---` 表示完成。

